from collections import deque
def comp(g,col=1):
    seen=[[col in row for _ in []] or None for _ in []]; H,W=len(g),len(g[0])
    seen=[[False]*W for _ in range(H)]
    out=[]
    for i in range(H):
        for j in range(W):
            if g[i][j]==col and not seen[i][j]:
                q=deque([(i,j)]); seen[i][j]=True;c=[]
                while q:
                    y,x=q.popleft(); c.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and g[ny][nx]==col and not seen[ny][nx]:
                            seen[ny][nx]=True;q.append((ny,nx))
                out.append(c)
    return out
