G=load()
def comp_size(gi,c,H,W):
    seen=set(); best=0
    for i in range(H):
        for j in range(W):
            if gi[i][j]==c and (i,j) not in seen:
                q=deque([(i,j)]); seen.add((i,j)); n=0
                while q:
                    x,y=q.popleft(); n+=1
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        a,b=(x+dx)%H,(y+dy)%W
                        if gi[a][b]==c and (a,b) not in seen: seen.add((a,b)); q.append((a,b))
                best=max(best,n)
    return best
